import React, { useState } from 'react';

function MapPanel({ openClaim }) {
  const [hoveredPin, setHoveredPin] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('all');

  const mapItems = [
    { id: 1, title: "Freshly baked sourdough", source: "Green Wheat Bakery", dist: "0.3 km", price: "Free", until: "2 hrs", type: "donation", x: 68, y: 152 },
    { id: 2, title: "Catered event leftovers", source: "Spice Garden Caterers", dist: "0.7 km", price: "₹80", until: "4 hrs", type: "discounted", x: 195, y: 148 },
    { id: 3, title: "Community pantry share", source: "City Food Bank", dist: "1.1 km", price: "Free", until: "Tomorrow", type: "community", x: 310, y: 230 },
    { id: 4, title: "Organic vegetable box", source: "Farm Direct Hub", dist: "1.8 km", price: "₹150", until: "6 hrs", type: "discounted", x: 430, y: 57 },
    { id: 5, title: "Dairy surplus", source: "Morning Fresh Dairy", dist: "2.4 km", price: "Free", until: "3 hrs", type: "donation", x: 68, y: 335 },
  ];

  const filteredItems = mapItems.filter(item => {
    const matchesSearch = item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         item.source.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterType === 'all' || item.type === filterType;
    return matchesSearch && matchesFilter;
  });

  const getPinColor = (type) => {
    switch (type) {
      case 'donation': return '#1D9E75';
      case 'discounted': return '#EF9F27';
      case 'community': return '#D85A30';
      default: return '#1D9E75';
    }
  };

  const getPinIcon = (type) => {
    switch (type) {
      case 'donation': return 'D';
      case 'discounted': return '$';
      case 'community': return 'C';
      default: return 'D';
    }
  };

  return (
    <div className="panel active">
      <div className="map-container">
        <div className="map-area">
          <svg className="map-svg" viewBox="0 0 500 380" xmlns="http://www.w3.org/2000/svg">
            {/* Background */}
            <rect width="500" height="380" fill="#EAF3DE" rx="12"/>
            
            {/* Water bodies */}
            <ellipse cx="450" cy="320" rx="30" ry="20" fill="#A8DADC" opacity="0.6"/>
            <ellipse cx="120" cy="50" rx="25" ry="15" fill="#A8DADC" opacity="0.6"/>
            
            {/* Parks */}
            <rect x="350" y="280" width="40" height="30" rx="8" fill="#B7E4C7" opacity="0.7"/>
            <rect x="50" y="80" width="35" height="25" rx="6" fill="#B7E4C7" opacity="0.7"/>
            
            {/* Roads */}
            <line x1="0" y1="190" x2="500" y2="190" stroke="#fff" strokeWidth="10" opacity="0.7"/>
            <line x1="250" y1="0" x2="250" y2="380" stroke="#fff" strokeWidth="8" opacity="0.7"/>
            <line x1="0" y1="100" x2="500" y2="100" stroke="#fff" strokeWidth="5" opacity="0.5"/>
            <line x1="0" y1="290" x2="500" y2="290" stroke="#fff" strokeWidth="5" opacity="0.5"/>
            <line x1="140" y1="0" x2="140" y2="380" stroke="#fff" strokeWidth="5" opacity="0.5"/>
            <line x1="380" y1="0" x2="380" y2="380" stroke="#fff" strokeWidth="5" opacity="0.5"/>
            
            {/* Road markings */}
            <line x1="0" y1="190" x2="500" y2="190" stroke="#FFE066" strokeWidth="1" strokeDasharray="5,5" opacity="0.5"/>
            <line x1="250" y1="0" x2="250" y2="380" stroke="#FFE066" strokeWidth="1" strokeDasharray="5,5" opacity="0.5"/>
            
            {/* Buildings/Blocks */}
            <rect x="20" y="115" width="100" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="155" y="115" width="80" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="260" y="115" width="100" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="20" y="205" width="100" height="75" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="155" y="205" width="80" height="75" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="260" y="205" width="100" height="75" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="390" y="115" width="95" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="390" y="205" width="95" height="75" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="20" y="20" width="100" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="155" y="20" width="80" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="260" y="20" width="100" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="390" y="20" width="95" height="65" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="20" y="305" width="100" height="60" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="155" y="305" width="80" height="60" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="260" y="305" width="100" height="60" rx="4" fill="#C0DD97" opacity="0.6"/>
            <rect x="390" y="305" width="95" height="60" rx="4" fill="#C0DD97" opacity="0.6"/>
            
            {/* Building details */}
            <rect x="35" y="130" width="15" height="20" rx="2" fill="#A8DADC" opacity="0.8"/>
            <rect x="55" y="125" width="12" height="25" rx="2" fill="#A8DADC" opacity="0.8"/>
            <rect x="170" y="130" width="18" height="15" rx="2" fill="#A8DADC" opacity="0.8"/>
            <rect x="275" y="125" width="14" height="22" rx="2" fill="#A8DADC" opacity="0.8"/>
            
            {/* Pins */}
            {mapItems.map(item => (
              <g key={item.id} 
                 transform={`translate(${item.x}, ${item.y})`}
                 onClick={() => openClaim({ title: item.title, provider: item.source, dist: item.dist, price: item.price, until: item.until })}
                 onMouseEnter={() => setHoveredPin(item.id)}
                 onMouseLeave={() => setHoveredPin(null)}
                 style={{cursor: 'pointer'}}>
                <circle cx="0" cy="0" r="16" fill={getPinColor(item.type)} opacity="0.2"/>
                <circle cx="0" cy="0" r="10" fill={getPinColor(item.type)}/>
                <text x="0" y="3" textAnchor="middle" fontSize="11" fill="white" fontWeight="700">{getPinIcon(item.type)}</text>
                {hoveredPin === item.id && (
                  <circle cx="0" cy="0" r="18" fill="none" stroke={getPinColor(item.type)} strokeWidth="2" opacity="0.8"/>
                )}
              </g>
            ))}
            
            {/* User location */}
            <g transform="translate(250,57)">
              <circle cx="0" cy="0" r="20" fill="#0F6E56" opacity="0.15"/>
              <circle cx="0" cy="0" r="12" fill="#0F6E56"/>
              <text x="0" y="4" textAnchor="middle" fontSize="11" fill="white" fontWeight="700">You</text>
              <circle cx="0" cy="0" r="22" fill="none" stroke="#0F6E56" strokeWidth="2" opacity="0.6"/>
            </g>
            
            {/* Legend */}
            <rect x="10" y="340" width="230" height="30" rx="6" fill="white" opacity="0.9"/>
            <circle cx="26" cy="355" r="7" fill="#1D9E75"/>
            <text x="38" y="359" fontSize="10" fill="#3B6D11">Donation</text>
            <circle cx="90" cy="355" r="7" fill="#EF9F27"/>
            <text x="102" y="359" fontSize="10" fill="#BA7517">Discounted</text>
            <circle cx="170" cy="355" r="7" fill="#D85A30"/>
            <text x="182" y="359" fontSize="10" fill="#993C1D">Community</text>
          </svg>
          
          {/* Tooltip */}
          {hoveredPin && (
            <div style={{
              position: 'absolute',
              left: `${mapItems.find(item => item.id === hoveredPin).x + 20}px`,
              top: `${mapItems.find(item => item.id === hoveredPin).y - 10}px`,
              background: 'white',
              padding: '8px 12px',
              borderRadius: '6px',
              boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
              fontSize: '12px',
              fontWeight: '500',
              pointerEvents: 'none',
              zIndex: 10
            }}>
              {mapItems.find(item => item.id === hoveredPin).title}
            </div>
          )}
        </div>
        
        <div className="map-sidebar">
          <div className="map-sidebar-header">
            <div className="map-sidebar-title">Find nearby listings</div>
            <input 
              type="text" 
              placeholder="Search food or provider..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="map-search"
            />
            <div className="map-filters">
              <button 
                className={`btn btn-sm ${filterType === 'all' ? 'btn-primary' : ''}`}
                onClick={() => setFilterType('all')}
              >
                All
              </button>
              <button 
                className={`btn btn-sm ${filterType === 'donation' ? 'btn-primary' : ''}`}
                onClick={() => setFilterType('donation')}
              >
                Free
              </button>
              <button 
                className={`btn btn-sm ${filterType === 'discounted' ? 'btn-primary' : ''}`}
                onClick={() => setFilterType('discounted')}
              >
                Paid
              </button>
            </div>
          </div>
          
          <div style={{fontSize:'12px',fontWeight:'500',color:'var(--color-text-secondary)',marginBottom:'4px'}}>
            {filteredItems.length} listings nearby
          </div>
          
          {filteredItems.map((item) => (
            <div key={item.id} className="map-item" onClick={() => openClaim({ title: item.title, provider: item.source, dist: item.dist, price: item.price, until: item.until })}>
              <div className="map-item-title">{item.title}</div>
              <div className="map-item-dist">{item.source} · {item.dist}</div>
              <div className="map-item-badge" style={{color: item.price === 'Free' ? 'var(--teal)' : 'var(--amber)'}}>{item.price} · {item.until}</div>
            </div>
          ))}
          
          {filteredItems.length === 0 && (
            <div className="map-empty">
              No listings match your search
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default MapPanel;
